import{_ as d,o as e,c as o,a2 as r}from"./chunks/framework.Boholvbs.js";const _=JSON.parse('{"title":"Environment variables","description":"Every PRIORICODE_* environment variable with effect and default, plus the third-party variables prioricode honors (AWS, Azure, Cloudflare, XDG, OTEL).","frontmatter":{"title":"Environment variables","description":"Every PRIORICODE_* environment variable with effect and default, plus the third-party variables prioricode honors (AWS, Azure, Cloudflare, XDG, OTEL)."},"headers":[],"relativePath":"reference/environment-variables.md","filePath":"reference/environment-variables.md"}'),a={name:"reference/environment-variables.md"};function c(i,t,E,n,l,s){return e(),o("div",null,[...t[0]||(t[0]=[r('<p>Truthiness for on/off vars: <code>1</code> or <code>true</code> (case-insensitive). Grouped by what they touch. Config-file equivalents usually exist — <a href="./config.html">config reference</a> — env wins as its own layer.</p><h2 id="paths-data" tabindex="-1">Paths &amp; data <a class="header-anchor" href="#paths-data" aria-label="Permalink to &quot;Paths &amp; data&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Effect</th><th>Default</th></tr></thead><tbody><tr><td><code>PRIORICODE_DB</code></td><td>DB file override — absolute, relative to data dir, or <code>:memory:</code></td><td>channel-routed file</td></tr><tr><td><code>PRIORICODE_DISABLE_CHANNEL_DB</code></td><td>force the shared <code>prioricode.db</code> regardless of channel</td><td>off</td></tr><tr><td><code>PRIORICODE_CONFIG_DIR</code></td><td>relocate/append the global config directory</td><td>XDG config</td></tr><tr><td><code>PRIORICODE_CONFIG</code></td><td>one extra config file, merged</td><td>—</td></tr><tr><td><code>PRIORICODE_CONFIG_CONTENT</code></td><td>inline config JSON(C), merged as local layer</td><td>—</td></tr><tr><td><code>PRIORICODE_DISABLE_PROJECT_CONFIG</code></td><td>skip <code>.prioricode</code> project discovery</td><td>off</td></tr><tr><td><code>PRIORICODE_TUI_CONFIG</code></td><td>extra <code>tui.json</code> file</td><td>—</td></tr><tr><td><code>PRIORICODE_INSTALL_DIR</code> / <code>XDG_BIN_DIR</code></td><td>installer target directory (<a href="./../getting-started/install.html">install</a>)</td><td></td></tr><tr><td><code>PRIORICODE_BIN_PATH</code></td><td>binary used by the npm launcher</td><td>autodetect</td></tr><tr><td><code>PRIORICODE_AUTH_CONTENT</code></td><td>inline auth JSON replacing <code>auth.json</code> contents</td><td>—</td></tr></tbody></table><h2 id="runtime-behavior" tabindex="-1">Runtime behavior <a class="header-anchor" href="#runtime-behavior" aria-label="Permalink to &quot;Runtime behavior&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Effect</th><th>Default</th></tr></thead><tbody><tr><td><code>PRIORICODE_PRINT_LOGS</code></td><td>stderr logging (flag <code>--print-logs</code>)</td><td>off</td></tr><tr><td><code>PRIORICODE_LOG_LEVEL</code></td><td><code>DEBUG</code>|<code>INFO</code>|<code>WARN</code>|<code>ERROR</code></td><td><code>INFO</code></td></tr><tr><td><code>PRIORICODE_PURE</code></td><td>skip external plugins (flag <code>--pure</code>)</td><td>off</td></tr><tr><td><code>PRIORICODE_CLIENT</code></td><td>client label sent to the API (<code>cli</code>, <code>acp</code>, …)</td><td><code>cli</code></td></tr><tr><td><code>PRIORICODE_PERMISSION</code></td><td>JSON permission rules merged over config</td><td>—</td></tr><tr><td><code>PRIORICODE_DISABLE_MOUSE</code></td><td>ignore mouse events in the TUI</td><td>off</td></tr><tr><td><code>PRIORICODE_DISABLE_TERMINAL_TITLE</code></td><td>don&#39;t write terminal titles</td><td>off</td></tr><tr><td><code>PRIORICODE_DISABLE_FFF</code></td><td>disable the fff file indexer (default-disabled on Windows)</td><td>per-OS</td></tr><tr><td><code>PRIORICODE_SHOW_TTFD</code></td><td>show time-to-first-delta metrics</td><td>off</td></tr><tr><td><code>PRIORICODE_AUTO_HEAP_SNAPSHOT</code></td><td>heap snapshot on OOM-ish failures</td><td>off</td></tr><tr><td><code>PRIORICODE_HOOK_DEPTH</code></td><td>internal hook-recursion guard</td><td>set by runtime</td></tr><tr><td><code>PRIORICODE_GIT_BASH_PATH</code></td><td>Windows: which bash to use</td><td>autodetect</td></tr><tr><td><code>PRIORICODE_FAKE_VCS</code></td><td>treat non-git dirs as VCS (testing)</td><td>off</td></tr><tr><td><code>PRIORICODE_NO_CLIPBOARD</code></td><td>skip clipboard helper install</td><td>off</td></tr></tbody></table><h2 id="server-remote" tabindex="-1">Server &amp; remote <a class="header-anchor" href="#server-remote" aria-label="Permalink to &quot;Server &amp; remote&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Effect</th><th>Default</th></tr></thead><tbody><tr><td><code>PRIORICODE_SERVER_PASSWORD</code></td><td>HTTP Basic auth for serve/web/attach/run <code>--attach</code>; unset ⇒ &quot;unsecured&quot; warning</td><td>none</td></tr><tr><td><code>PRIORICODE_SERVER_USERNAME</code></td><td>basic-auth username</td><td><code>prioricode</code></td></tr></tbody></table><h2 id="sharing" tabindex="-1">Sharing <a class="header-anchor" href="#sharing" aria-label="Permalink to &quot;Sharing&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Effect</th><th>Default</th></tr></thead><tbody><tr><td><code>PRIORICODE_AUTO_SHARE</code></td><td>auto-share sessions (= <code>share: &quot;auto&quot;</code>)</td><td>off</td></tr><tr><td><code>PRIORICODE_DISABLE_SHARE</code></td><td>kill sharing entirely (= <code>share: &quot;disabled&quot;</code>)</td><td>off</td></tr></tbody></table><h2 id="updates" tabindex="-1">Updates <a class="header-anchor" href="#updates" aria-label="Permalink to &quot;Updates&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Effect</th><th>Default</th></tr></thead><tbody><tr><td><code>PRIORICODE_DISABLE_AUTOUPDATE</code></td><td>never check/apply updates</td><td>off</td></tr><tr><td><code>PRIORICODE_ALWAYS_NOTIFY_UPDATE</code></td><td>notify-only mode for the updater</td><td>off</td></tr><tr><td><code>VERSION</code></td><td>pin installer version (<code>install</code>, <code>upgrade</code>)</td><td>latest</td></tr></tbody></table><h2 id="model-catalog" tabindex="-1">Model catalog <a class="header-anchor" href="#model-catalog" aria-label="Permalink to &quot;Model catalog&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Effect</th><th>Default</th></tr></thead><tbody><tr><td><code>PRIORICODE_MODELS_URL</code></td><td>catalog service base</td><td>hosted default (built-in)</td></tr><tr><td><code>PRIORICODE_MODELS_PATH</code></td><td>local JSON catalog file</td><td>disk cache</td></tr><tr><td><code>PRIORICODE_DISABLE_MODELS_FETCH</code></td><td>never fetch; local only</td><td>off</td></tr><tr><td><code>PRIORICODE_ENABLE_EXPERIMENTAL_MODELS</code></td><td>include experimental catalog entries</td><td>off</td></tr></tbody></table><h2 id="compaction-tools" tabindex="-1">Compaction &amp; tools <a class="header-anchor" href="#compaction-tools" aria-label="Permalink to &quot;Compaction &amp; tools&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Effect</th><th>Default</th></tr></thead><tbody><tr><td><code>PRIORICODE_DISABLE_AUTOCOMPACT</code></td><td>force <code>compaction.auto: false</code></td><td>off</td></tr><tr><td><code>PRIORICODE_DISABLE_PRUNE</code></td><td>force <code>compaction.prune: false</code></td><td>off</td></tr><tr><td><code>PRIORICODE_WEBSEARCH_PROVIDER</code></td><td><code>exa</code> or <code>parallel</code> for web search</td><td>deterministic split per session</td></tr><tr><td><code>PRIORICODE_ENABLE_EXA</code> / <code>PRIORICODE_ENABLE_PARALLEL</code></td><td>enable that search provider</td><td>off</td></tr><tr><td><code>EXA_API_KEY</code> / <code>PARALLEL_API_KEY</code></td><td>bring-your-own search keys</td><td>via hosted default route</td></tr></tbody></table><h2 id="cross-session-coordination" tabindex="-1">Cross-session coordination <a class="header-anchor" href="#cross-session-coordination" aria-label="Permalink to &quot;Cross-session coordination&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Effect</th><th>Default</th></tr></thead><tbody><tr><td><code>PRIORICODE_DISABLE_COORDINATION_RESPONDER</code></td><td>no responder children; requests escalate to humans</td><td>off</td></tr><tr><td><code>PRIORICODE_COORDINATION_RATE_LIMIT_PER_MINUTE</code></td><td>per-sender send budget</td><td><code>10</code></td></tr><tr><td><code>PRIORICODE_COORDINATION_DEDUPE_WINDOW_MS</code></td><td>identical-repeat suppression window</td><td><code>300000</code></td></tr><tr><td><code>PRIORICODE_COORDINATION_INBOX_CAP</code></td><td>max unread inbox rows</td><td><code>50</code></td></tr><tr><td><code>PRIORICODE_COORDINATION_ESCALATION_MS</code></td><td>unanswered-request escalation deadline</td><td><code>900000</code> (15 min)</td></tr><tr><td><code>PRIORICODE_COORDINATION_EXPIRY_GRACE_MS</code></td><td>grace after escalation before expiry</td><td><code>900000</code></td></tr></tbody></table><h2 id="experimental-flag-gated-features" tabindex="-1">Experimental (flag-gated features) <a class="header-anchor" href="#experimental-flag-gated-features" aria-label="Permalink to &quot;Experimental (flag-gated features)&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>These switch on in-flux surfaces. Names, behavior, and existence can change between releases — don&#39;t build CI on them without pinning a version.</p></div><table tabindex="0"><thead><tr><th>Variable</th><th>Enables</th></tr></thead><tbody><tr><td><code>PRIORICODE_EXPERIMENTAL</code></td><td>umbrella: turns on most of the below where implemented</td></tr><tr><td><code>PRIORICODE_EXPERIMENTAL_WORKSPACES</code> (+ <code>PRIORICODE_WORKSPACE_ID</code>)</td><td><code>/workspaces</code>, <code>/warp</code></td></tr><tr><td><code>PRIORICODE_EXPERIMENTAL_REFERENCES</code></td><td>references surface</td></tr><tr><td><code>PRIORICODE_EXPERIMENTAL_FILEWATCHER</code> / <code>_DISABLE_FILEWATCHER</code></td><td>watcher mode</td></tr><tr><td><code>PRIORICODE_EXPERIMENTAL_DISABLE_COPY_ON_SELECT</code></td><td>terminal copy behavior (default-on Windows)</td></tr><tr><td><code>PRIORICODE_EXPERIMENTAL_CODE_MODE</code></td><td>the <code>execute</code> code-mode tool (<a href="./../extending/mcp.html">MCP page</a>)</td></tr><tr><td><code>PRIORICODE_EXPERIMENTAL_LSP_TOOL</code></td><td>the <code>lsp</code> tool (<a href="./../extending/lsp.html">LSP page</a>)</td></tr><tr><td><code>PRIORICODE_EXPERIMENTAL_LSP_TY</code></td><td>python: ty instead of pyright</td></tr><tr><td><code>PRIORICODE_EXPERIMENTAL_OXFMT</code></td><td>oxfmt formatter</td></tr><tr><td><code>PRIORICODE_EXPERIMENTAL_BACKGROUND_SUBAGENTS</code></td><td><code>ctrl+b</code> backgrounding + task <code>background</code></td></tr><tr><td><code>PRIORICODE_EXPERIMENTAL_PLAN_MODE</code></td><td>plan-mode surface</td></tr><tr><td><code>PRIORICODE_EXPERIMENTAL_EVENT_SYSTEM</code> / <code>_WEBSOCKETS</code></td><td>v2 event transport</td></tr><tr><td><code>PRIORICODE_EXPERIMENTAL_NATIVE_LLM</code></td><td>native LLM client path</td></tr><tr><td><code>PRIORICODE_EXPERIMENTAL_ICON_DISCOVERY</code></td><td>icon discovery</td></tr><tr><td><code>PRIORICODE_EXPERIMENTAL_OUTPUT_TOKEN_MAX</code></td><td>output-token ceiling experiment</td></tr><tr><td><code>PRIORICODE_EXPERIMENTAL_BASH_DEFAULT_TIMEOUT_MS</code></td><td>override the 2-minute bash default</td></tr><tr><td><code>PRIORICODE_ENABLE_QUESTION_TOOL</code></td><td>question tool for non-standard clients</td></tr><tr><td><code>PRIORICODE_ENABLE_EXA</code>/<code>PRIORICODE_EXPERIMENTAL_EXA</code>, <code>PRIORICODE_ENABLE_PARALLEL</code>/<code>…_EXPERIMENTAL_PARALLEL</code></td><td>websearch providers</td></tr></tbody></table><h2 id="claude-code-plugin-compat" tabindex="-1">Claude-code &amp; plugin compat <a class="header-anchor" href="#claude-code-plugin-compat" aria-label="Permalink to &quot;Claude-code &amp; plugin compat&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Effect</th><th>Default</th></tr></thead><tbody><tr><td><code>PRIORICODE_DISABLE_EXTERNAL_SKILLS</code></td><td>skip <code>~/.claude/skills</code>, <code>~/.agents/skills</code> scans</td><td>off</td></tr><tr><td><code>PRIORICODE_DISABLE_CLAUDE_CODE</code> / <code>_PROMPT</code> / <code>_SKILLS</code></td><td>skip Claude-compatible CLAUDE.md prompt / skills</td><td>off</td></tr><tr><td><code>PRIORICODE_DISABLE_DEFAULT_PLUGINS</code></td><td>unregister built-in auth plugins</td><td>off</td></tr><tr><td><code>PRIORICODE_DISABLE_LSP_DOWNLOAD</code></td><td>no language-server provisioning</td><td>off</td></tr><tr><td><code>PRIORICODE_DISABLE_EMBEDDED_WEB_UI</code></td><td>server stops serving the bundled UI (desktop uses this)</td><td>off</td></tr><tr><td><code>PRIORICODE_PLUGIN_META_FILE</code></td><td>plugin metadata cache location</td><td>data dir</td></tr></tbody></table><h2 id="third-party-variables-honored" tabindex="-1">Third-party variables honored <a class="header-anchor" href="#third-party-variables-honored" aria-label="Permalink to &quot;Third-party variables honored&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Used for</th></tr></thead><tbody><tr><td><code>ANTHROPIC_API_KEY</code>, <code>OPENAI_API_KEY</code>, <code>GOOGLE_GENERATIVE_AI_API_KEY</code>, …</td><td>provider env auth (full per-provider list from the catalog; <code>providers list</code> shows what&#39;s set)</td></tr><tr><td><code>PRIORICODE_API_KEY</code></td><td>hosted PrioriCode provider key</td></tr><tr><td><code>AWS_PROFILE</code>, <code>AWS_REGION</code>, <code>AWS_ACCESS_KEY_ID</code>, <code>AWS_BEARER_TOKEN_BEDROCK</code>, <code>AWS_WEB_IDENTITY_TOKEN_FILE</code>, <code>AWS_CONTAINER_CREDENTIALS_RELATIVE_URI</code>/<code>_FULL_URI</code></td><td>Amazon Bedrock chain</td></tr><tr><td><code>AZURE_RESOURCE_NAME</code>, <code>AZURE_COGNITIVE_SERVICES_RESOURCE_NAME</code></td><td>Azure endpoints</td></tr><tr><td><code>CLOUDFLARE_GATEWAY_ID</code>, <code>CLOUDFLARE_ACCOUNT_ID</code>, <code>CLOUDFLARE_API_TOKEN</code></td><td>Cloudflare AI Gateway</td></tr><tr><td><code>EXA_API_KEY</code>, <code>PARALLEL_API_KEY</code></td><td>web search (<a href="./tools.html">tools</a>)</td></tr><tr><td><code>EDITOR</code>, <code>VISUAL</code></td><td><code>/editor</code>, <code>/export</code>, command editing</td></tr><tr><td><code>OTEL_EXPORTER_OTLP_ENDPOINT</code>, <code>OTEL_EXPORTER_OTLP_HEADERS</code>, <code>OTEL_RESOURCE_ATTRIBUTES</code></td><td>OpenTelemetry export when <code>experimental.openTelemetry</code></td></tr><tr><td><code>XDG_DATA_HOME</code>, <code>XDG_CONFIG_HOME</code>, <code>XDG_CACHE_HOME</code>, <code>XDG_STATE_HOME</code></td><td>base for all data dirs</td></tr><tr><td><code>SHELL</code>, <code>TERM</code>, <code>TERM_PROGRAM</code>, <code>TERM_PROGRAM_VERSION</code></td><td>shell choice, IDE/terminal detection</td></tr><tr><td><code>PRIORICODE_CALLER</code> (<code>vscode</code>/<code>vscode-insiders</code>), <code>ZED_TERM</code></td><td>editor integration detection</td></tr><tr><td><code>HOME</code>, <code>TMPDIR</code>, <code>USER</code>, <code>PATH</code></td><td>standard</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../configure/files.html">Config files</a> — Env&#39;s position in the merge order. <ul><li><a href="./../using/coordination.html">Coordination</a> — What the coordination knobs actually tune.</li><li><a href="./../support/troubleshooting.html">Troubleshooting</a> — Which switches to flip when diagnosing.</li></ul></li></ul>',26)])])}const O=d(a,[["render",c]]);export{_ as __pageData,O as default};
